#include "unity.h"
#include "mock_dht22.h"
#include "mock_platform_io.h"
#include "mpu6050.h"
#include "sensors.h"
#include "dht22.h"
#include "platform_io.h"
#include "app_config.h"

#include <stdint.h>

#define TEST_MPU_WHO_AM_I_REG 0x75U
#define TEST_MPU_ACCEL_CONFIG_REG 0x1CU
#define TEST_MPU_ACCEL_XOUT_REG 0x3BU
#define TEST_MPU_EXPECTED_ID 0x68U
#define TEST_MPU_RANGE_4G 0x08U

typedef struct
{
    bool saw_accel_config_write;
    uint8_t accel_config_value;
} init_probe_t;

static init_probe_t init_probe;
static uint32_t process_time_ms;
static uint32_t acceleration_request_times[4];
static uint32_t acceleration_request_count;
static uint8_t conversion_bytes[6];

static bool init_probe_read(uint8_t address, uint8_t reg, uint8_t *bytes,
                            uint16_t length)
{
    (void)address;
    if ((bytes == NULL) || (length != 1U))
    {
        return false;
    }
    if (reg == TEST_MPU_WHO_AM_I_REG)
    {
        bytes[0] = TEST_MPU_EXPECTED_ID;
    }
    else if (reg == TEST_MPU_ACCEL_CONFIG_REG)
    {
        bytes[0] = TEST_MPU_RANGE_4G;
    }
    else
    {
        bytes[0] = 0U;
    }
    return true;
}

static bool init_probe_write(uint8_t address, uint8_t reg, uint8_t value)
{
    (void)address;
    if (reg == TEST_MPU_ACCEL_CONFIG_REG)
    {
        init_probe.saw_accel_config_write = true;
        init_probe.accel_config_value = value;
    }
    return true;
}

static bool conversion_read(uint8_t address, uint8_t reg, uint8_t *bytes,
                            uint16_t length)
{
    (void)address;
    (void)reg;
    if ((bytes == NULL) || (length != sizeof(conversion_bytes)))
    {
        return false;
    }
    for (uint16_t i = 0U; i < length; i++)
    {
        bytes[i] = conversion_bytes[i];
    }
    return true;
}

static bool platform_read_callback(uint8_t address, uint8_t reg,
                                   uint8_t *bytes, uint16_t length,
                                   int cmock_num_calls)
{
    (void)address;
    (void)cmock_num_calls;
    if (bytes == NULL)
    {
        return false;
    }
    if (length == 1U)
    {
        if (reg == TEST_MPU_WHO_AM_I_REG)
        {
            bytes[0] = TEST_MPU_EXPECTED_ID;
        }
        else if (reg == TEST_MPU_ACCEL_CONFIG_REG)
        {
            bytes[0] = TEST_MPU_RANGE_4G;
        }
        else
        {
            bytes[0] = 0U;
        }
        return true;
    }
    if ((length == 6U) && (reg == TEST_MPU_ACCEL_XOUT_REG))
    {
        bytes[0] = 0U;
        bytes[1] = 0U;
        bytes[2] = 0U;
        bytes[3] = 0U;
        bytes[4] = 0U;
        bytes[5] = 0U;
        if (acceleration_request_count <
            (sizeof(acceleration_request_times) /
             sizeof(acceleration_request_times[0])))
        {
            acceleration_request_times[acceleration_request_count] =
                process_time_ms;
        }
        acceleration_request_count++;
        return true;
    }
    return false;
}

void setUp(void)
{
    init_probe.saw_accel_config_write = false;
    init_probe.accel_config_value = 0U;
    process_time_ms = 0U;
    acceleration_request_count = 0U;
    for (uint32_t i = 0U;
         i < (sizeof(acceleration_request_times) /
              sizeof(acceleration_request_times[0]));
         i++)
    {
        acceleration_request_times[i] = 0U;
    }
    for (uint32_t i = 0U; i < sizeof(conversion_bytes); i++)
    {
        conversion_bytes[i] = 0U;
    }
}

void tearDown(void)
{
}

void test_FR_007_01(void)
{
    const mpu6050_io_t io = {
        .read = init_probe_read,
        .write = init_probe_write,
        .address = APP_MPU_ADDRESS
    };

    TEST_ASSERT_TRUE(mpu6050_init(&io));
    TEST_ASSERT_TRUE(init_probe.saw_accel_config_write);
    TEST_ASSERT_EQUAL_INT(TEST_MPU_RANGE_4G, init_probe.accel_config_value);
}

void test_FR_007_02(void)
{
    platform_io_read_StubWithCallback(platform_read_callback);
    platform_io_write_IgnoreAndReturn(true);
    platform_io_log_Ignore();

    sensors_init(0U);

    process_time_ms = 9U;
    sensors_process(process_time_ms);
    process_time_ms = 10U;
    sensors_process(process_time_ms);
    process_time_ms = 19U;
    sensors_process(process_time_ms);
    process_time_ms = 20U;
    sensors_process(process_time_ms);

    TEST_ASSERT_EQUAL_INT(2, acceleration_request_count);
    TEST_ASSERT_EQUAL_INT(10, acceleration_request_times[0]);
    TEST_ASSERT_EQUAL_INT(20, acceleration_request_times[1]);
}

void test_FR_007_03(void)
{
    const mpu6050_io_t io = {
        .read = conversion_read,
        .write = init_probe_write,
        .address = APP_MPU_ADDRESS
    };
    mpu6050_sample_t sample = {0.0F, 0.0F, 0.0F};

    /* Big-endian raw X=8192; raw Y and Z are zero. */
    conversion_bytes[0] = 0x20U;
    conversion_bytes[1] = 0x00U;
    conversion_bytes[2] = 0x00U;
    conversion_bytes[3] = 0x00U;
    conversion_bytes[4] = 0x00U;
    conversion_bytes[5] = 0x00U;

    TEST_ASSERT_TRUE(mpu6050_read(&io, &sample));
    TEST_ASSERT_FLOAT_WITHIN(0.0001F, 1.0F, sample.x_g);
    TEST_ASSERT_FLOAT_WITHIN(0.0001F, 0.0F, sample.y_g);
    TEST_ASSERT_FLOAT_WITHIN(0.0001F, 0.0F, sample.z_g);
}
